#include <errno.h>
#include <signal.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

static void on_alarm(int sig) { (void)sig; }   /* just interrupt */

int main(int argc, char **argv) {
    int restart = argc > 1;                 /* any argument: SA_RESTART */
    struct sigaction sa = {0};
    sa.sa_handler = on_alarm;
    sa.sa_flags = restart ? SA_RESTART : 0;
    sigaction(SIGALRM, &sa, NULL);

    int p[2];
    pipe(p);
    if (fork() == 0) {                      /* child: write after 2 s */
        sleep(2);
        write(p[1], "hi", 2);
        _exit(0);
    }
    alarm(1);                               /* SIGALRM after 1 s */
    struct timespec t0, t1;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    char buf[16];
    ssize_t n = read(p[0], buf, sizeof buf);    /* empty pipe: sleeps */
    clock_gettime(CLOCK_MONOTONIC, &t1);
    double s = (t1.tv_sec - t0.tv_sec) + (t1.tv_nsec - t0.tv_nsec) / 1e9;
    if (n < 0) printf("after %.1f s: read = -1, errno = %s\n", s, strerror(errno));
    else       printf("after %.1f s: read = %zd bytes\n", s, n);
    return 0;
}

/* On macOS (Apple Silicon), same POSIX rules:
$ ./eintr
after 1.0 s: read = -1, errno = Interrupted system call
$ ./eintr restart
after 2.0 s: read = 2 bytes */

ssize_t write_all(int fd, const char *buf, size_t len) {
    size_t done = 0;
    while (done < len) {
        ssize_t n = write(fd, buf + done, len - done);
        if (n < 0) {
            if (errno == EINTR)
                continue;     /* nothing written: retry */
            return -1;        /* real error */
        }
        done += n;            /* short write: advance, loop */
    }
    return done;
}

/* write_all() as traced above, plus counters */
static void tick(int s) { (void)s; }

int main(void) {
    int p[2]; pipe(p);
    if (fork() == 0) {                       /* child: slow reader */
        close(p[1]); char b[4096]; ssize_t n; long tot = 0;
        while ((n = read(p[0], b, sizeof b)) > 0) { tot += n; usleep(50); }
        printf("reader got %ld bytes\n", tot); fflush(stdout); _exit(0);
    }
    close(p[0]);
    struct sigaction sa = {0};
    sa.sa_handler = tick;                    /* no SA_RESTART */
    sigaction(SIGALRM, &sa, NULL);
    struct itimerval it = {{0, 1000}, {0, 1000}};   /* SIGALRM every 1 ms */
    setitimer(ITIMER_REAL, &it, NULL);

    static char buf[1 << 20];                /* 1 MiB */
    ssize_t r = write_all(p[1], buf, sizeof buf);
    printf("write_all returned %zd: %ld calls, %ld short, %ld EINTR\n",
           r, calls, shorts, eintrs);
    close(p[1]); wait(NULL);
    return 0;
}

