#include <fcntl.h>
#include <stdio.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>

int main(int argc, char **argv) {
    int fd = open(argv[1], O_RDONLY);
    struct stat st;
    fstat(fd, &st);                       /* file size in st.st_size */
    unsigned char *p = mmap(NULL, st.st_size, PROT_READ,
                            MAP_PRIVATE, fd, 0);
    if (p == MAP_FAILED) { perror("mmap"); return 1; }
    close(fd);                            /* the mapping stays valid */

    unsigned long sum = 0;
    for (off_t i = 0; i < st.st_size; i++)
        sum += p[i];                      /* page faults happen here */
    printf("%lu\n", sum);
    munmap(p, st.st_size);
    return 0;
}

#include <setjmp.h>
#include <signal.h>
#include <stdio.h>
#include <sys/mman.h>
#include <unistd.h>

static sigjmp_buf env;
static void on_segv(int s) { siglongjmp(env, s); }

static void try(const char *what, char *addr, int write) {
    int sig = sigsetjmp(env, 1);
    if (sig == 0) {
        if (write) *(volatile char *)addr = 1;
        else       (void)*(volatile char *)addr;
        printf("%-14s ok\n", what);
    } else {
        printf("%-14s %s\n", what, sig == SIGSEGV ? "SIGSEGV" : "SIGBUS");
    }
}

int main(void) {
    long pg = sysconf(_SC_PAGESIZE);
    struct sigaction sa = {0};
    sa.sa_handler = on_segv;
    sigaction(SIGSEGV, &sa, NULL);
    sigaction(SIGBUS, &sa, NULL);

    char *p = mmap(NULL, 4 * pg, PROT_READ | PROT_WRITE,
                   MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    mprotect(p + 2 * pg, pg, PROT_READ);   /* page 2 read-only */
    munmap(p + 1 * pg, pg);                /* page 1 gone */

    try("read  page 0", p, 0);
    try("write page 1", p + 1 * pg, 1);
    try("read  page 2", p + 2 * pg, 0);
    try("write page 2", p + 2 * pg, 1);
    try("write page 3", p + 3 * pg, 1);
    return 0;
}

/* Run on macOS (Apple Silicon, 16 KiB pages):
read  page 0   ok
write page 1   SIGSEGV
read  page 2   ok
write page 2   SIGBUS
write page 3   ok */

#include <stdatomic.h>
#include <stdio.h>
#include <sys/mman.h>
#include <sys/wait.h>
#include <unistd.h>
#define N 8
#define LD(x, o) atomic_load_explicit(&(x), memory_order_##o)
#define ST(x, v) atomic_store_explicit(&(x), (v), memory_order_release)

struct ring { _Atomic unsigned head, tail; int slot[N]; };

int main(void) {
    struct ring *r = mmap(NULL, sizeof *r, PROT_READ | PROT_WRITE,
                          MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (r == MAP_FAILED) { perror("mmap"); return 1; }
    if (fork() == 0) {                          /* consumer */
        long sum = 0;
        for (int got = 0; got < 10; got++) {
            unsigned t = LD(r->tail, relaxed);
            while (LD(r->head, acquire) == t) ;      /* empty: spin */
            sum += r->slot[t % N];
            ST(r->tail, t + 1);                      /* free the slot */
        }
        printf("consumer: sum of 10 messages = %ld\n", sum);
        return 0;
    }
    for (int i = 1; i <= 10; i++) {             /* producer */
        unsigned h = LD(r->head, relaxed);
        while (h - LD(r->tail, acquire) == N) ;     /* full: spin */
        r->slot[h % N] = i * 100;                    /* plain store */
        ST(r->head, h + 1);                          /* publish it */
    }
    wait(NULL);
    printf("producer: head = %u, tail = %u\n", LD(r->head, relaxed),
           LD(r->tail, relaxed));
    return 0;
}
/* macOS (Apple Silicon), two runs, identical:
consumer: sum of 10 messages = 5500
producer: head = 10, tail = 10 */

#include <fcntl.h>
#include <stdio.h>
#include <unistd.h>

int main(int argc, char **argv) {
    int fd = open(argv[1], O_RDONLY);
    if (fd < 0) { perror("open"); return 1; }
    static unsigned char buf[4096];
    unsigned long sum = 0;
    ssize_t n;
    while ((n = read(fd, buf, sizeof buf)) > 0)   /* one syscall per 4 KiB */
        for (ssize_t i = 0; i < n; i++)
            sum += buf[i];
    printf("%lu\n", sum);
    close(fd);
    return 0;
}

/* Commands to run on Linux (not run here):
   head -c 100M /dev/urandom > big.bin       # 104,857,600 bytes
   strace -c ./sumread big.bin               # read() version
   strace -c ./summap  big.bin               # mmap version from the mmap lesson */

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    char *small = malloc(100 * 1024);   /* below the 128 KiB threshold */
    char *big   = malloc(200 * 1024);   /* above it */
    small[0] = big[0] = 1;
    printf("%p %p\n", (void *)small, (void *)big);
    free(big);                          /* munmap */
    free(small);                        /* back to malloc's free lists */
    return 0;
}

/* Linux, not run here:  strace -e trace=%memory ./alloc
   Expect brk calls for the heap (the 100 KiB block), then one
   anonymous mmap of a little over 200 KiB for the big block,
   and a matching munmap when it is freed. */

#include <errno.h>
#include <linux/audit.h>
#include <linux/filter.h>
#include <linux/seccomp.h>
#include <stddef.h>
#include <stdio.h>
#include <sys/prctl.h>
#include <sys/syscall.h>
#include <time.h>
#include <unistd.h>

#define ALLOW(nr) BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, (nr), 0, 1), \
                  BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_ALLOW)

int main(void) {
    struct sock_filter f[] = {
        BPF_STMT(BPF_LD | BPF_W | BPF_ABS, offsetof(struct seccomp_data, arch)),
        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, AUDIT_ARCH_X86_64, 1, 0),
        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_KILL_PROCESS),
        BPF_STMT(BPF_LD | BPF_W | BPF_ABS, offsetof(struct seccomp_data, nr)),
        ALLOW(SYS_read), ALLOW(SYS_write), ALLOW(SYS_exit_group),
        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_ERRNO | EPERM),
    };
    struct sock_fprog prog = { sizeof f / sizeof f[0], f };
    prctl(PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0);
    prctl(PR_SET_SECCOMP, SECCOMP_MODE_FILTER, &prog);

    long pid = syscall(SYS_getpid);       /* not on the list */
    int e = errno;
    struct timespec ts;
    int t = clock_gettime(CLOCK_MONOTONIC, &ts);   /* vDSO */
    char msg[64];
    int len = snprintf(msg, sizeof msg, "getpid=%ld errno=%d clock=%d\n",
                       pid, e, t);
    write(1, msg, len);
    return 0;                             /* exit_group: allowed */
}

#include <linux/seccomp.h>
#include <sys/prctl.h>
#include <sys/syscall.h>
#include <unistd.h>

int main(void) {
    prctl(PR_SET_SECCOMP, SECCOMP_MODE_STRICT);
    write(1, "write is allowed\n", 17);
    syscall(SYS_exit, 0);    /* exit, not exit_group: allowed */
}
